bounded_host_request.command:
set -euo pipefail
mapfile -t ids < <(docker ps -q --filter label=com.docker.compose.service=gaybbs)
test "${#ids[@]}" -eq 1 || exit 61
docker exec "${ids[0]}" node --input-type=module -e '
import fs from "node:fs";
try {
  const p=process.env.BOT_TOKEN_FILE;
  const token=p?fs.readFileSync(p,"utf8").trim():process.env.BOT_TOKEN;
  if(!token)process.exit(62);
  const response=await fetch("https://api.telegram.org/bot"+token+"/getMe",{signal:AbortSignal.timeout(10000)});
  const body=await response.json();
  if(!body.ok)process.exit(63);
  if(body.result?.supports_inline_queries!==true)process.exit(64);
  console.log("GAYBBS_INLINE_QUERY_FLAG=PASS");
}catch{process.exit(65)}
'
